INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES
('o9-A1-1', 'q9000001-0000-0000-0000-000000000001', 'Menambah fitur aplikasi', 0, 'Keliru. Menambah fitur bukan tujuan utama evaluasi kegunaan.'),
('o9-A1-2', 'q9000001-0000-0000-0000-000000000001', 'Menemukan masalah penggunaan produk', 10, 'Tepat! Usability Testing berfokus mengamati pengguna nyata untuk menemukan hambatan dan masalah saat memakai produk.'),
('o9-A1-3', 'q9000001-0000-0000-0000-000000000001', 'Mendesain logo', 0, 'Keliru. Mendesain logo masuk ke tahap perancangan identitas visual.'),
('o9-A1-4', 'q9000001-0000-0000-0000-000000000001', 'Mengelola server', 0, 'Keliru. Pengelolaan server termasuk ranah DevOps/infrastruktur.'),
('o9-A2-1', 'q9000001-0000-0000-0000-000000000002', '1-2 orang', 0, 'Keliru. Jumlah 1-2 orang terlalu sedikit untuk menangkap pola masalah UX.'),
('o9-A2-2', 'q9000001-0000-0000-0000-000000000002', '3-5 orang', 10, 'Tepat! Mengacu pada aturan Nielsen, pengujian dengan 3-5 pengguna sudah mampu mengungkap sekitar 85% masalah usability utama.'),
('o9-A2-3', 'q9000001-0000-0000-0000-000000000002', '10-15 orang', 0, 'Keliru. Jumlah terlalu besar menyebabkan pengulangan temuan yang sama dan pemborosan sumber daya.'),
('o9-A2-4', 'q9000001-0000-0000-0000-000000000002', '20 orang', 0, 'Keliru. 20 responden lebih cocok untuk survei kuantitatif, bukan sesi UT kualitatif.'),
('o9-A3-1', 'q9000001-0000-0000-0000-000000000003', 'Diam selama pengujian', 0, 'Keliru. Jika pengguna diam, fasilitator tidak dapat mengetahui alasan di balik tindakan atau kebingungan mereka.'),
('o9-A3-2', 'q9000001-0000-0000-0000-000000000003', 'Menjelaskan apa yang dipikirkan saat menggunakan produk', 10, 'Tepat! Metode Think-Aloud meminta partisipan menyuarakan pikiran, ekspektasi, dan kebingungan secara langsung.'),
('o9-A3-3', 'q9000001-0000-0000-0000-000000000003', 'Mengisi survei tanpa mencoba produk', 0, 'Keliru. Usability Testing wajib melibatkan interaksi langsung dengan produk.'),
('o9-A3-4', 'q9000001-0000-0000-0000-000000000003', 'Menulis kode', 0, 'Keliru.'),
('o9-A4-1', 'q9000001-0000-0000-0000-000000000004', 'Memberikan petunjuk terus-menerus', 0, 'Keliru. Memberi petunjuk akan membiaskan hasil pengujian.'),
('o9-A4-2', 'q9000001-0000-0000-0000-000000000004', 'Membimbing setiap langkah pengguna', 0, 'Keliru. Bimbingan menutup celah desain yang seharusnya ditemukan saat pengguna kebingungan.'),
('o9-A4-3', 'q9000001-0000-0000-0000-000000000004', 'Mengamati tanpa banyak intervensi', 10, 'Tepat! Fasilitator berperan sebagai pengamat netral agar perilaku alami pengguna terlihat apa adanya.'),
('o9-A4-4', 'q9000001-0000-0000-0000-000000000004', 'Menjawab semua kesulitan pengguna', 0, 'Keliru. Fasilitator justru perlu mencatat di titik mana pengguna mengalami kesulitan.'),
('o9-A5-1', 'q9000001-0000-0000-0000-000000000005', 'Tidak melakukan testing', 0, 'Keliru.'),
('o9-A5-2', 'q9000001-0000-0000-0000-000000000005', 'Tidak memberi arahan saat peserta menjalankan tugas', 10, 'Tepat! Prinsip No Guidance memastikan hasil pengujian objektif karena pengguna mengandalkan intuisi antarmuka sepenuhnya.'),
('o9-A5-3', 'q9000001-0000-0000-0000-000000000005', 'Tidak mencatat hasil testing', 0, 'Keliru. Dokumentasi temuan wajib dilakukan.'),
('o9-A5-4', 'q9000001-0000-0000-0000-000000000005', 'Tidak merekam sesi', 0, 'Keliru.'),
('o9-A6-1', 'q9000001-0000-0000-0000-000000000006', 'Mendesain UI', 0, 'Keliru. Desain UI dilakukan di Figma.'),
('o9-A6-2', 'q9000001-0000-0000-0000-000000000006', 'Menganalisis perilaku pengguna', 10, 'Tepat! Microsoft Clarity menyediakan rekaman sesi, heatmap, dan deteksi rage/dead click untuk memahami interaksi pengguna.'),
('o9-A6-3', 'q9000001-0000-0000-0000-000000000006', 'Membuat database', 0, 'Keliru.'),
('o9-A6-4', 'q9000001-0000-0000-0000-000000000006', 'Hosting aplikasi', 0, 'Keliru.'),
('o9-A7-1', 'q9000001-0000-0000-0000-000000000007', 'Melihat rekaman interaksi pengguna', 10, 'Tepat! Session Replay memutar ulang pergerakan kursor, guliran layar, dan klik pengguna saat menjelajahi aplikasi.'),
('o9-A7-2', 'q9000001-0000-0000-0000-000000000007', 'Mengedit video', 0, 'Keliru.'),
('o9-A7-3', 'q9000001-0000-0000-0000-000000000007', 'Membuat prototype', 0, 'Keliru.'),
('o9-A7-4', 'q9000001-0000-0000-0000-000000000007', 'Mengelola repository', 0, 'Keliru.'),
('o9-A8-1', 'q9000001-0000-0000-0000-000000000008', 'Struktur database', 0, 'Keliru.'),
('o9-A8-2', 'q9000001-0000-0000-0000-000000000008', 'Area yang sering berinteraksi dengan pengguna', 10, 'Tepat! Heatmap memvisualisasikan intensitas klik, gerakan, dan kedalaman scroll menggunakan gradasi warna.'),
('o9-A8-3', 'q9000001-0000-0000-0000-000000000008', 'Kecepatan server', 0, 'Keliru.'),
