('o9-A9-1', 'q9000001-0000-0000-0000-000000000009', 'Menutup aplikasi', 0, 'Keliru.'),
('o9-A9-2', 'q9000001-0000-0000-0000-000000000009', 'Berkali-kali mengklik karena frustrasi', 10, 'Tepat! Rage Click menandakan elemen merespons lambat, macet, atau menipu ekspektasi pengguna sehingga diklik berulang kali.'),
('o9-A9-3', 'q9000001-0000-0000-0000-000000000009', 'Login berulang kali', 0, 'Keliru.'),
('o9-A9-4', 'q9000001-0000-0000-0000-000000000009', 'Menghapus akun', 0, 'Keliru.'),
('o9-A10-1', 'q9000001-0000-0000-0000-000000000010', 'Klik pada elemen yang tidak memberikan respons yang diharapkan', 10, 'Tepat! Dead Click terjadi saat pengguna mengira teks/gambar bisa diklik (seperti tombol/tautan), tetapi tidak ada aksi apa pun.'),
('o9-A10-2', 'q9000001-0000-0000-0000-000000000010', 'Klik kanan mouse', 0, 'Keliru.'),
('o9-A10-3', 'q9000001-0000-0000-0000-000000000010', 'Klik pada tombol logout', 0, 'Keliru.'),
('o9-A10-4', 'q9000001-0000-0000-0000-000000000010', 'Klik pada link aktif', 0, 'Keliru.'),
('o9-B1-1', 'q9000003-0000-0000-0000-000000000001', 'Tingkat keberhasilan pengguna menyelesaikan tugas', 10, 'Tepat! Task Success Rate menghitung persentase skenario tugas yang berhasil diselesaikan secara tuntas oleh partisipan.'),
('o9-B1-2', 'q9000003-0000-0000-0000-000000000001', 'Jumlah pengguna baru', 0, 'Keliru. Jumlah pengguna baru merupakan metrik akuisisi (acquisition).'),
('o9-B1-3', 'q9000003-0000-0000-0000-000000000001', 'Durasi coding', 0, 'Keliru.'),
('o9-B1-4', 'q9000003-0000-0000-0000-000000000001', 'Kecepatan internet', 0, 'Keliru.'),
('o9-B2-1', 'q9000003-0000-0000-0000-000000000002', 'Kepuasan pengguna', 0, 'Keliru. Persepsi kemudahan/kepuasan diukur menggunakan metrik seperti SEQ atau SUS.'),
('o9-B2-2', 'q9000003-0000-0000-0000-000000000002', 'Waktu yang dibutuhkan menyelesaikan tugas', 10, 'Tepat! Time-on-Task mengukur efisiensi alur produk berdasarkan durasi penyelesaian skenario oleh pengguna.'),
('o9-B2-3', 'q9000003-0000-0000-0000-000000000002', 'Jumlah bug', 0, 'Keliru.'),
