('o9-B3-1', 'q9000003-0000-0000-0000-000000000003', 'System Evaluation Question', 0, 'Keliru.'),
('o9-B3-2', 'q9000003-0000-0000-0000-000000000003', 'Single Ease Question', 10, 'Tepat! SEQ (Single Ease Question) adalah pertanyaan tunggal pasca-tugas untuk menilai tingkat kemudahan skenario.'),
('o9-B3-3', 'q9000003-0000-0000-0000-000000000003', 'Simple Error Query', 0, 'Keliru.'),
