('o9-B4-1', 'q9000003-0000-0000-0000-000000000004', 'Keuntungan produk', 0, 'Keliru.'),
('o9-B4-2', 'q9000003-0000-0000-0000-000000000004', 'Persepsi kemudahan tugas oleh pengguna', 10, 'Tepat! SEQ mengukur seberapa mudah atau sulit suatu tugas dirasakan langsung oleh partisipan setelah menyelesaikannya.'),
('o9-B4-3', 'q9000003-0000-0000-0000-000000000004', 'Jumlah klik', 0, 'Keliru.'),
