('o9-B5-2', 'q9000003-0000-0000-0000-000000000005', '1–7', 10, 'Tepat! Rentang nilai SEQ adalah 1 (Sangat Sulit) hingga 7 (Sangat Mudah), dengan target rata-rata ideal >= 5.'),
('o9-B5-3', 'q9000003-0000-0000-0000-000000000005', '1–10', 0, 'Keliru.'),
('o9-B5-4', 'q9000003-0000-0000-0000-000000000005', '0–100', 0, 'Keliru. Skala 0-100 digunakan pada System Usability Scale (SUS).'),
('o9-B6-1', 'q9000003-0000-0000-0000-000000000006', 'Jelas dan realistis', 10, 'Tepat! Skenario tugas harus menyerupai situasi nyata pengguna tanpa membocorkan langkah atau label tombol di UI.'),
('o9-B6-2', 'q9000003-0000-0000-0000-000000000006', 'Rumit dan ambigu', 0, 'Keliru. Skenario ambigu membuat pengujian tidak valid karena peserta bingung memahami instruksi.'),
