('o9-B8-1', 'q9000003-0000-0000-0000-000000000008', 'Kritis', 10, 'Tepat! Setiap kendala yang memblokir pengguna menuntaskan tugas inti diklasifikasikan sebagai masalah Kritis.'),
('o9-B8-2', 'q9000003-0000-0000-0000-000000000008', 'Kosmetik', 0, 'Keliru.'),
