INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES
('er-0000009-0000-0000-0000-000000000001', 'q9000002-0000-0000-0000-000000000001', 'Usability Testing adalah metode evaluasi yang melibatkan pengguna nyata untuk menguji kemudahan penggunaan suatu produk dan menemukan masalah yang dialami saat menyelesaikan tugas tertentu.', ARRAY['usability testing', 'pengguna nyata', 'evaluasi', 'kemudahan penggunaan', 'menemukan masalah']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Testing aplikasi kepada pengguna (terlalu umum)","8":"Pengujian untuk melihat apakah aplikasi bisa digunakan (belum menjelaskan keterlibatan pengguna nyata dan tujuan evaluasi usability)","9":"Pengujian produk kepada pengguna untuk menemukan masalah penggunaan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000009-0000-0000-0000-000000000002', 'q9000002-0000-0000-0000-000000000002', 'Karena membantu menemukan hambatan penggunaan, memvalidasi desain, meningkatkan pengalaman pengguna, dan mengurangi risiko kegagalan produk setelah dirilis.', ARRAY['validasi', 'pengalaman pengguna', 'hambatan', 'risiko']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Dilakukan sebelum rilis (tidak menjelaskan alasannya)","8":"Membantu meningkatkan aplikasi (belum menjelaskan manfaat validasi dan pengurangan risiko)","9":"Membantu menemukan masalah sebelum produk digunakan banyak orang","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000009-0000-0000-0000-000000000003', 'q9000002-0000-0000-0000-000000000003', 'Think-Aloud adalah metode usability testing di mana pengguna mengungkapkan pikiran, kebingungan, alasan, dan keputusan mereka secara verbal selama menjalankan tugas.', ARRAY['think aloud', 'berbicara', 'pikiran pengguna', 'proses berpikir']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000009-0000-0000-0000-000000000004', 'q9000002-0000-0000-0000-000000000004', 'No Guidance berarti fasilitator tidak memberikan arahan atau bantuan selama tugas berlangsung agar hasil pengujian mencerminkan pengalaman pengguna yang sebenarnya.', ARRAY['no guidance', 'tanpa arahan', 'objektif', 'pengalaman nyata']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000009-0000-0000-0000-000000000005', 'q9000002-0000-0000-0000-000000000005', 'Microsoft Clarity digunakan untuk menganalisis perilaku pengguna melalui heatmap, session replay, rage click, dan insight lainnya guna menemukan masalah UX.', ARRAY['clarity', 'heatmap', 'replay', 'perilaku pengguna', 'ux']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000009-0000-0000-0000-000000000006', 'q9000004-0000-0000-0000-000000000001', 'Session Replay memungkinkan tim melihat kembali interaksi pengguna sehingga dapat memahami hambatan dan kesalahan yang terjadi selama penggunaan aplikasi.', ARRAY['session replay', 'rekaman', 'interaksi pengguna', 'hambatan']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000009-0000-0000-0000-000000000007', 'q9000004-0000-0000-0000-000000000002', 'Heatmap menunjukkan area halaman yang paling sering diklik, dilihat, atau diinteraksikan oleh pengguna.', ARRAY['heatmap', 'klik', 'interaksi', 'area populer']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000009-0000-0000-0000-000000000008', 'q9000004-0000-0000-0000-000000000003', 'Rage Click adalah perilaku pengguna yang mengklik berulang kali pada suatu elemen karena frustrasi atau ekspektasi yang tidak terpenuhi.', ARRAY['rage click', 'klik berulang', 'frustrasi']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Pengguna sering klik (terlalu umum)","8":"Klik berulang pada tombol (belum menjelaskan penyebab frustrasi pengguna)","9":"Klik berkali-kali karena pengguna bingung atau kesal","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000009-0000-0000-0000-000000000009', 'q9000004-0000-0000-0000-000000000004', 'Dead Click terjadi ketika pengguna mengklik suatu elemen tetapi tidak mendapatkan respons yang diharapkan.', ARRAY['dead click', 'tidak ada respons', 'ekspektasi pengguna']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000009-0000-0000-0000-000000000010', 'q9000004-0000-0000-0000-000000000005', 'Task Success Rate adalah metrik yang mengukur persentase pengguna yang berhasil menyelesaikan tugas yang diberikan.', ARRAY['task success rate', 'persentase keberhasilan', 'tugas pengguna']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000009-0000-0000-0000-000000000011', 'q9000006-0000-0000-0000-000000000001', 'Time-on-Task digunakan untuk mengukur waktu yang dibutuhkan pengguna dalam menyelesaikan suatu tugas.', ARRAY['time on task', 'waktu', 'menyelesaikan tugas']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000009-0000-0000-0000-000000000012', 'q9000006-0000-0000-0000-000000000002', 'SEQ adalah pertanyaan penilaian yang diberikan setelah tugas selesai untuk mengetahui seberapa mudah tugas tersebut menurut pengguna pada skala 1–7.', ARRAY['seq', 'kemudahan', 'skala 1-7', 'persepsi pengguna']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000009-0000-0000-0000-000000000013', 'q9000006-0000-0000-0000-000000000003', 'Karena membantu tim mengurutkan prioritas perbaikan berdasarkan tingkat dampak dan urgensi sehingga sumber daya digunakan secara efektif.', ARRAY['prioritas', 'dampak', 'urgensi', 'triase']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000009-0000-0000-0000-000000000014', 'q9000006-0000-0000-0000-000000000004', 'GitHub Issue digunakan untuk mendokumentasikan masalah, melacak progres perbaikan, dan memudahkan koordinasi tim.', ARRAY['issue', 'dokumentasi', 'tracking', 'koordinasi']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000009-0000-0000-0000-000000000015', 'q9000006-0000-0000-0000-000000000005', 'Karena prompt yang spesifik memberikan konteks yang jelas sehingga AI dapat menghasilkan solusi yang lebih akurat, relevan, dan sesuai dengan masalah yang dihadapi.', ARRAY['prompt spesifik', 'konteks', 'akurat', 'solusi relevan']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Prompt harus jelas (terlalu umum dan tidak menjelaskan dampaknya terhadap hasil AI)","8":"Prompt spesifik membuat AI lebih mudah memahami masalah (belum menjelaskan hubungan antara konteks dan kualitas solusi)","9":"Prompt spesifik membantu AI memberikan jawaban lebih tepat","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb);
